BEGIN TRANSACTION;
CREATE TABLE check_ins (
	check_in_id VARCHAR(30) NOT NULL, 
	employee_id VARCHAR(20) NOT NULL, 
	cycle_id VARCHAR(30) NOT NULL, 
	check_in_date DATE NOT NULL, 
	progress_percent FLOAT NOT NULL, 
	notes TEXT, 
	rationale TEXT, 
	PRIMARY KEY (check_in_id), 
	FOREIGN KEY(employee_id) REFERENCES employees (employee_id), 
	FOREIGN KEY(cycle_id) REFERENCES review_cycles (cycle_id)
);
CREATE TABLE competencies (
	competency_id VARCHAR(30) NOT NULL, 
	name VARCHAR(100) NOT NULL, 
	description TEXT, 
	PRIMARY KEY (competency_id), 
	UNIQUE (name)
);
CREATE TABLE development_plans (
	development_plan_id VARCHAR(30) NOT NULL, 
	employee_id VARCHAR(20) NOT NULL, 
	review_id VARCHAR(30) NOT NULL, 
	objective VARCHAR(255) NOT NULL, 
	action TEXT NOT NULL, 
	target_date DATE NOT NULL, 
	status VARCHAR(30) NOT NULL, 
	approval_status VARCHAR(20) NOT NULL, 
	approved_by VARCHAR(20), 
	approved_at DATETIME, 
	PRIMARY KEY (development_plan_id), 
	FOREIGN KEY(employee_id) REFERENCES employees (employee_id), 
	FOREIGN KEY(review_id) REFERENCES reviews (review_id), 
	FOREIGN KEY(approved_by) REFERENCES managers (manager_id)
);
CREATE TABLE employees (
	employee_id VARCHAR(20) NOT NULL, 
	full_name VARCHAR(120) NOT NULL, 
	email VARCHAR(150) NOT NULL, 
	department VARCHAR(80) NOT NULL, 
	job_title VARCHAR(100) NOT NULL, 
	hire_date DATE NOT NULL, 
	employment_status VARCHAR(30) NOT NULL, 
	manager_id VARCHAR(20), 
	PRIMARY KEY (employee_id), 
	UNIQUE (email), 
	FOREIGN KEY(manager_id) REFERENCES managers (manager_id)
);
CREATE TABLE event_history (
	event_id VARCHAR(30) NOT NULL, 
	cycle_id VARCHAR(30) NOT NULL, 
	entity_type VARCHAR(50) NOT NULL, 
	record_id VARCHAR(80) NOT NULL, 
	event_type VARCHAR(50) NOT NULL, 
	actor_id VARCHAR(20), 
	event_time DATETIME NOT NULL, 
	reason TEXT, 
	PRIMARY KEY (event_id), 
	FOREIGN KEY(cycle_id) REFERENCES review_cycles (cycle_id)
);
CREATE TABLE feedback (
	feedback_id VARCHAR(30) NOT NULL, 
	employee_id VARCHAR(20) NOT NULL, 
	competency_id VARCHAR(30), 
	cycle_id VARCHAR(30) NOT NULL, 
	author_id VARCHAR(20), 
	feedback_type VARCHAR(20) NOT NULL, 
	evidence_reference VARCHAR(255), 
	rating FLOAT NOT NULL, 
	comments TEXT NOT NULL, 
	feedback_date DATE NOT NULL, 
	PRIMARY KEY (feedback_id), 
	FOREIGN KEY(employee_id) REFERENCES employees (employee_id), 
	FOREIGN KEY(competency_id) REFERENCES competencies (competency_id), 
	FOREIGN KEY(cycle_id) REFERENCES review_cycles (cycle_id)
);
CREATE TABLE goals (
	goal_id VARCHAR(60) NOT NULL, 
	employee_id VARCHAR(20) NOT NULL, 
	cycle_id VARCHAR(30) NOT NULL, 
	title VARCHAR(200) NOT NULL, 
	status VARCHAR(30) NOT NULL, 
	progress_percent FLOAT NOT NULL, 
	created_date DATE NOT NULL, 
	PRIMARY KEY (goal_id), 
	FOREIGN KEY(employee_id) REFERENCES employees (employee_id), 
	FOREIGN KEY(cycle_id) REFERENCES review_cycles (cycle_id)
);
CREATE TABLE key_results (
	key_result_id VARCHAR(80) NOT NULL, 
	goal_id VARCHAR(60) NOT NULL, 
	description VARCHAR(255) NOT NULL, 
	target_value FLOAT NOT NULL, 
	current_value FLOAT NOT NULL, 
	unit VARCHAR(50) NOT NULL, 
	PRIMARY KEY (key_result_id), 
	FOREIGN KEY(goal_id) REFERENCES goals (goal_id)
);
CREATE TABLE manager_assignment_history (
	assignment_id VARCHAR(30) NOT NULL, 
	employee_id VARCHAR(20) NOT NULL, 
	manager_id VARCHAR(20) NOT NULL, 
	effective_from DATE NOT NULL, 
	effective_to DATE, 
	reason TEXT, 
	recorded_at DATETIME NOT NULL, 
	PRIMARY KEY (assignment_id), 
	FOREIGN KEY(employee_id) REFERENCES employees (employee_id), 
	FOREIGN KEY(manager_id) REFERENCES managers (manager_id)
);
CREATE TABLE managers (
	manager_id VARCHAR(20) NOT NULL, 
	full_name VARCHAR(120) NOT NULL, 
	email VARCHAR(150) NOT NULL, 
	department VARCHAR(80) NOT NULL, 
	PRIMARY KEY (manager_id), 
	UNIQUE (email)
);
CREATE TABLE review_cycles (
	cycle_id VARCHAR(30) NOT NULL, 
	name VARCHAR(100) NOT NULL, 
	start_date DATE NOT NULL, 
	end_date DATE NOT NULL, 
	status VARCHAR(20) NOT NULL, 
	PRIMARY KEY (cycle_id)
);
CREATE TABLE reviews (
	review_id VARCHAR(30) NOT NULL, 
	employee_id VARCHAR(20) NOT NULL, 
	cycle_id VARCHAR(30) NOT NULL, 
	reviewer_id VARCHAR(20) NOT NULL, 
	score FLOAT NOT NULL, 
	status VARCHAR(30) NOT NULL, 
	review_date DATE NOT NULL, 
	PRIMARY KEY (review_id), 
	FOREIGN KEY(employee_id) REFERENCES employees (employee_id), 
	FOREIGN KEY(cycle_id) REFERENCES review_cycles (cycle_id), 
	FOREIGN KEY(reviewer_id) REFERENCES managers (manager_id)
);
COMMIT;
